powerpagecomponent.content:
{
  "source": "{% comment %}
Platform Renderer — CLEAN APP + CONTENT MODE

✅ Supports content pages (sections + layouts)
✅ Supports app pages via sections--acceptance-router
✅ Router bypasses all layout + section constraints
✅ Minimal + safe (no schema changes)
{% endcomment %}

{% assign debugParam = request.params.debug | default: '' | downcase | strip %}
{% assign DEBUG = false %}
{% if debugParam == '1' or debugParam == 'true' %}
  {% assign DEBUG = true %}
{% endif %}

{% assign galleryParam = request.params.gallery | default: '' | downcase | strip %}

{% assign currentEntryPointRaw = page.adx_partialurl | default: '' | downcase | strip %}
{% assign currentEntryPoint = currentEntryPointRaw %}
{% if currentEntryPoint == '/' %}{% assign currentEntryPoint = '' %}{% endif %}
{% assign currentEntryPoint = currentEntryPoint | replace: '/', '' | strip %}

{% assign requestedSlug = request.params.page | default: '' | downcase | strip %}
{% assign resolvedSlug = requestedSlug %}
{% if resolvedSlug == '' and currentEntryPoint == '' %}
  {% assign resolvedSlug = 'home' %}
{% endif %}

<div class="hit-page">

{% if DEBUG %}
  <div style="background:#000;color:#0f0;padding:6px;font-size:11px;">
    DEBUG → slug={{ resolvedSlug }}
  </div>
{% endif %}

{% if resolvedSlug != '' %}

  {% fetchxml pageQuery %}
  <fetch top="1">
    <entity name="hit_platformpage">
      <attribute name="hit_platformpageid" />
      <attribute name="hit_slug" />
      <filter>
        <condition attribute="hit_slug" operator="eq" value="{{ resolvedSlug }}" />
        <condition attribute="hit_isactive" operator="eq" value="1" />
      </filter>
    </entity>
  </fetch>
  {% endfetchxml %}

  {% assign pageRec = pageQuery.results.entities | first %}

  {% if pageRec %}

    {% fetchxml sectionQuery %}
    <fetch>
      <entity name="hit_platformpagesection">
        <attribute name="hit_platformpagesectionid" />
        <attribute name="hit_name" />
        <attribute name="hit_sortorder" />
        <attribute name="hit_sectionlayout" />
        <attribute name="hit_isvisible" />
        <attribute name="hit_backgroundbleed" />
        <attribute name="hit_contentwidthmode" />
        <attribute name="hit_sectioncolour" />
        <attribute name="hit_headingtext" />
        <attribute name="hit_introtext" />
        <attribute name="hit_showimage" />
        <attribute name="hit_mediaurl" />
        <order attribute="hit_sortorder" />
        <filter>
          <condition attribute="hit_platformpage" operator="eq" value="{{ pageRec.hit_platformpageid }}" />
        </filter>
        <link-entity name="hit_platformsectionlayout"
                     alias="layout"
                     from="hit_platformsectionlayoutid"
                     to="hit_sectionlayout"
                     link-type="outer">
          <attribute name="hit_template" />
        </link-entity>
      </entity>
    </fetch>
    {% endfetchxml %}

    {% assign sections = sectionQuery.results.entities %}

    <div class="hit-page__content">

    {% for section in sections %}

      {% if section.hit_isvisible != false %}

        {% assign sectionId = section.hit_platformpagesectionid %}
        {% assign layoutTemplate = section['layout.hit_template'] | default: '' | downcase | strip %}

        {% if DEBUG %}
          <div style="background:black;color:cyan;padding:4px;">
            sectionId = {{ sectionId }}
          </div>
        {% endif %}


        {% fetchxml slotQuery %}
        <fetch>
          <entity name="hit_platformpageslot">
            <attribute name="hit_platformpageslotid" />
              <attribute name="hit_name" />
              <attribute name="hit_slotindex" />
              <attribute name="hit_pagesection" />
              <attribute name="hit_sectiontype" />
              <!-- NEW: override governance fields -->
              <attribute name="hit_allowqueryoverride" />
              <attribute name="hit_contexttype" />
              <!-- existing slot content fields (from your screenshot) -->
              <attribute name="hit_ctabuttonlabel" />
              <attribute name="hit_ctaurl" />
              <attribute name="hit_ctatext" />
              <attribute name="hit_ctaenabled" />
              <attribute name="hit_contenttitle" />
              <attribute name="hit_contentdesc" />
              <attribute name="hit_contentvalign" />
              <attribute name="hit_contenthalign" />
              <attribute name="hit_contentwidth" />
              <attribute name="hit_contentheight" />
              <attribute name="hit_contentstyle" />
              <attribute name="hit_textcolourstyle" />
              <attribute name="hit_mediatype" />
              <attribute name="hit_mediaurl" />
              <attribute name="hit_mediafit" />
              <attribute name="hit_webgalleryconfig" />
              <attribute name="hit_article" />
              <attribute name="hit_program" />
              <attribute name="hit_persona" />
              <attribute name="hit_offering" />
              <attribute name="hit_fallbackimageurl" />
              <attribute name="hit_displaystyle" />
              <attribute name="hit_displayvariant" />
              <attribute name="hit_maxcolumns" />
              <attribute name="hit_maxrows" />
            <filter>
              <condition attribute="hit_pagesection" operator="eq" value="{{ sectionId }}" />
            </filter>
            <link-entity name="hit_platformpagesectiontype"
                         alias="stype"
                         from="hit_platformpagesectiontypeid"
                         to="hit_sectiontype"
                         link-type="outer">
              <attribute name="hit_templatename" />
            </link-entity>
            <order attribute="hit_slotindex" />
          </entity>
        </fetch>
        {% endfetchxml %}

        {% assign slots = slotQuery.results.entities %}

{% if DEBUG %}
  <div style="background:black;color:lime;padding:4px;">
    layoutTemplate = {{ section['layout.hit_template'] }}
  </div>

  <div style="background:black;color:yellow;padding:4px;">
    slots count = {{ slots.size }}
  </div>
{% endif %}

        {% assign isRouter = false %}
        {% for slot in slots %}
          {% assign tn = slot['stype.hit_templatename'] | downcase %}
          {% if tn == 'sections--acceptance-router' %}
            {% assign isRouter = true %}
          {% endif %}
        {% endfor %}

        {% if isRouter %}

          <!-- ✅ APPLICATION MODE -->
          {% for slot in slots %}
            {% assign templateName = slot['stype.hit_templatename'] | downcase %}

            {% if DEBUG %}
              <div style="background:#222;color:#0ff;padding:4px;font-size:11px;">
                APP slot={{ slot.hit_name }} → {{ templateName }}
              </div>
            {% endif %}

            {% if templateName == 'sections--acceptance-router' %}
              {% include templateName section: section slot: slot debug: DEBUG galleryParam: galleryParam %}
            {% endif %}
          {% endfor %}

      {% else %}

<!-- ✅ CONTENT MODE -->

{% assign sectionColour = section.hit_sectioncolour.label | default:'None' | downcase | strip %}
{% assign backgroundBleed = section.hit_backgroundbleed.label | default:'Full' | downcase | strip %}
{% assign contentWidth = section.hit_contentwidthmode.label | default:'Inherit' | downcase | strip %}

{% assign showImage = section.hit_showimage %}
{% assign mediaUrl = section.hit_mediaurl | default:'' | strip %}

{% assign hasBackgroundImage = false %}
{% if showImage and mediaUrl != '' %}
  {% assign hasBackgroundImage = true %}
{% endif %}

<section
    class="
        hit-section
        section-colour-{{ sectionColour | replace:' ','-' }}
        bgbleed-{{ backgroundBleed | replace:' ','-' }}
        {% if hasBackgroundImage %}has-background-image{% endif %}
    "

    {% if hasBackgroundImage %}
    style="
        background-image:url('{{ mediaUrl }}');
        background-size:cover;
        background-position:center center;
        background-repeat:no-repeat;
    "
    {% endif %}
>

  <div class="
      hit-section__inner
      content-width-{{ contentWidth | replace:' ','-' }}
  ">

    {% if DEBUG %}
      <div style="background:#333;color:#fff;padding:4px;font-size:11px;">
        CONTENT
        | layout={{ layoutTemplate }}
        | colour={{ sectionColour }}
        | bleed={{ backgroundBleed }}
        | width={{ contentWidth }}
        | image={{ hasBackgroundImage }}
      </div>
    {% endif %}

    {% if layoutTemplate != '' %}

      {% include layoutTemplate  section: section  slots: slots  debug: DEBUG  galleryParam: galleryParam  galleryOverride: galleryOverride  %}

    {% else %}

      {% if DEBUG %}
        <div style="color:red;">
          ❌ No layout assigned to section
        </div>
      {% endif %}

    {% endif %}

  </div>

</section>

      {% endif %}


      {% endif %}

    {% endfor %}

    </div>

  {% else %}
    <div style="color:red;">❌ Page not found</div>
  {% endif %}

{% endif %}

</div>

<style>

  /* ==========================================================
   CONTENT WIDTH
========================================================== */

.layout--narrow {
    max-width: 800px;
}

.layout--medium {
    max-width: 1200px;
}

.layout--wide {
    max-width: 1600px;
}

.layout--full {
    max-width: none;
    width: 100%;
}

/* ==========================================================
   HORIZONTAL ALIGNMENT
========================================================== */

.layout--left {
    margin-left: 0;
    margin-right: auto;
}

.layout--centre {
    margin-left: auto;
    margin-right: auto;
}

.layout--right {
    margin-left: auto;
    margin-right: 0;
}
</style>
"
}
